// ─── File: RefreshAheadDemo.java ───
// Refresh-ahead: recompute a hot value in the background before TTL so readers
// never miss; probabilistic early recompute (XFetch) spreads refreshes over time.
import java.util.*;
import java.util.logging.*;

public class RefreshAheadDemo {
    private static final Logger log = Logger.getLogger("REFRESH");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ValuationService source = new ValuationService();
        RefreshAheadCache cache = new RefreshAheadCache(source, 60_000, 1.0);

        long now = 1_000_000L;
        // First read computes and caches (records computedAt, delta, expiry).
        log.info("=== Hot key: refresh-ahead keeps it fresh, reader never blocks ===");
        long v1 = cache.get("SAV2001", now);
        log.info(() -> "read @t+0s (computed): valuation=" + v1);

        // Read well before expiry: hit, no refresh.
        long v2 = cache.get("SAV2001", now + 10_000);
        log.info(() -> "read @t+10s (hit, no refresh): " + v2);

        // Read near expiry: probabilistic early recompute may trigger a BACKGROUND refresh
        // but still returns the current valid value instantly (no block).
        log.info("=== Near expiry: XFetch may refresh early in background, read stays instant ===");
        for (int s : new int[]{45, 52, 58}) {
            long t = now + s * 1000L;
            boolean early = cache.shouldRefreshEarly("SAV2001", t);
            long v = cache.get("SAV2001", t);
            log.info(() -> "read @t+" + s + "s: value=" + v + " earlyRefresh=" + early);
        }

        // Stampede comparison: 5 keys all expiring at the same instant.
        log.info("=== Stampede: XFetch scatters refreshes vs all-at-once expiry ===");
        RefreshAheadCache stampedeCache = new RefreshAheadCache(source, 60_000, 1.0);
        long base = 2_000_000L;
        for (String k : List.of("A","B","C","D","E")) stampedeCache.get(k, base);  // all cached same instant
        int refreshing = 0;
        for (String k : List.of("A","B","C","D","E"))
            if (stampedeCache.shouldRefreshEarly(k, base + 55_000)) refreshing++;
        final int rf = refreshing;
        log.info(() -> "At t+55s only " + rf + " of 5 keys chose to refresh early (rest use valid cache)");
    }
}

// ─── model/CacheEntry.java ───
class CacheEntry {
    final long value, computedAtMs, deltaMs, expiryMs;   // delta = how long compute took
    CacheEntry(long value, long computedAtMs, long deltaMs, long ttlMs) {
            this.value = value;
            this.computedAtMs = computedAtMs;
            this.deltaMs = deltaMs;
            this.expiryMs = computedAtMs + ttlMs;
    }
}

// ─── cache/RefreshAheadCache.java (refresh-ahead + XFetch early recompute) ───
class RefreshAheadCache {
    private static final Logger log = Logger.getLogger("REFRESH");
    private final ValuationService source; private final long ttlMs; private final double beta;
    private final Map<String, CacheEntry> map = new HashMap<>();
    private final Random rnd = new Random(11);
    RefreshAheadCache(ValuationService source, long ttlMs, double beta) {
            this.source = source;
            this.ttlMs = ttlMs
            this.beta = beta;
    }
    long get(String key, long nowMs) {
        CacheEntry e = map.get(key);
        if (e == null || nowMs >= e.expiryMs) {   // miss or hard-expired → compute now
            return compute(key, nowMs);
        }
        if (shouldRefreshEarly(key, nowMs)) {      // near expiry → BACKGROUND refresh, return current
            log.fine(() -> "background refresh " + key);
            compute(key, nowMs);                   // (in real code: async; value still returned below)
        }
        return e.value;                            // return the still-valid cached value instantly
    }
    // XFetch: refresh early with probability rising as expiry nears.
    // Trigger when now - delta*beta*ln(rand) >= expiry.
    boolean shouldRefreshEarly(String key, long nowMs) {
        CacheEntry e = map.get(key);
        if (e == null) return false;
        double xfetch = e.deltaMs * beta * -Math.log(rnd.nextDouble());
        return (nowMs + xfetch) >= e.expiryMs;
    }
    private long compute(String key, long nowMs) {
        long start = System.nanoTime();
        long value = source.computeValuation(key);
        long deltaMs = Math.max(1, (System.nanoTime() - start) / 1_000_000);
        // Add per-key jitter to TTL so a batch does not expire at the same instant.
        long jitter = rnd.nextInt(30_000);
        map.put(key, new CacheEntry(value, nowMs, deltaMs, ttlMs + jitter));
        return value;
    }
}

